#!/usr/bin/env bash
set -euo pipefail

cd ~/atlas-sandra
mkdir -p dashboard_static/backups
[ -f dashboard_static/index.html ] && cp dashboard_static/index.html "dashboard_static/backups/index.$(date +%Y%m%d_%H%M%S).html"

cat > dashboard_static/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>ATLAS Trading Command Center</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&family=JetBrains+Mono:wght@400;700&display=swap" rel="stylesheet">
<script src="https://unpkg.com/lucide@latest"></script>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
:root{--bg:#0a0a0f;--card:rgba(255,255,255,.035);--border:rgba(255,255,255,.08);--green:#00ff88;--red:#ff3366;--amber:#ffaa00;--blue:#00aaff;--muted:#8c92a3;--text:#f4f7fb}
*{box-sizing:border-box}body{margin:0;color:var(--text);font-family:Inter,sans-serif;background:radial-gradient(circle at 15% 5%,rgba(0,255,136,.09),transparent 28%),radial-gradient(circle at 85% 20%,rgba(0,170,255,.08),transparent 30%),linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px),var(--bg);background-size:auto,auto,36px 36px,36px 36px}.mono{font-family:"JetBrains Mono",monospace}.shell{display:grid;grid-template-columns:240px 1fr 330px;min-height:100vh}aside{position:sticky;top:0;height:100vh;padding:22px 16px;border-right:1px solid var(--border);background:rgba(10,10,15,.78);backdrop-filter:blur(18px)}main{padding:18px 22px;min-width:0}.right{position:sticky;top:0;height:100vh;padding:18px 16px;border-left:1px solid var(--border);background:rgba(10,10,15,.68);overflow:auto}.brand{display:flex;align-items:center;gap:12px;margin-bottom:28px}.logo{width:42px;height:42px;border-radius:14px;background:linear-gradient(135deg,rgba(0,255,136,.24),rgba(0,170,255,.16));border:1px solid rgba(0,255,136,.25);display:grid;place-items:center}h1{font-size:18px;letter-spacing:.1em;margin:0}.brand small{color:var(--muted)}.dot,.pulse{width:8px;height:8px;border-radius:99px;background:currentColor;display:inline-block;box-shadow:0 0 16px currentColor;animation:pulse 1.4s infinite}@keyframes pulse{50%{opacity:.35;transform:scale(.84)}}nav{display:grid;gap:7px}.nav{border:0;background:transparent;color:#aeb6c7;display:flex;gap:11px;align-items:center;padding:12px;border-radius:14px;cursor:pointer;font-weight:700;text-align:left}.nav:hover,.nav.active{color:white;background:rgba(255,255,255,.065);box-shadow:inset 0 0 0 1px var(--border)}.sidefoot{position:absolute;bottom:18px;left:16px;right:16px;padding:14px;border:1px solid var(--border);border-radius:18px;background:var(--card);color:var(--muted);font-size:12px}.sidefoot div{display:flex;justify-content:space-between;margin:6px 0}header{height:74px;display:flex;justify-content:space-between;align-items:center;border:1px solid var(--border);border-radius:22px;background:var(--card);backdrop-filter:blur(18px);padding:0 18px;margin-bottom:18px}.head{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.pill{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--border);background:rgba(255,255,255,.045);padding:8px 10px;border-radius:999px;font-size:12px;font-weight:800;color:#cbd5e1}.green{color:var(--green)}.red{color:var(--red)}.amber{color:var(--amber)}.blue{color:var(--blue)}.pnl{font:800 22px "JetBrains Mono"}.title{display:flex;justify-content:space-between;align-items:end;margin:12px 0 18px}.title h2{font-size:30px;line-height:1;margin:0}.title p,.sub{color:var(--muted);font-size:12px}.grid{display:grid;gap:16px}.kpis{grid-template-columns:repeat(4,1fr)}.two{grid-template-columns:2fr 1fr}.three{grid-template-columns:repeat(3,1fr)}.card{border:1px solid var(--border);border-radius:22px;background:var(--card);backdrop-filter:blur(18px);padding:18px;box-shadow:0 24px 80px rgba(0,0,0,.25);position:relative;overflow:hidden}.card h3{margin:0 0 12px;font-size:14px}.metric{font:800 30px "JetBrains Mono";letter-spacing:-.04em}.chip{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--border);border-radius:999px;padding:7px 9px;font-size:12px;color:#d7deea;background:rgba(255,255,255,.04);margin:3px}.btn{border:1px solid var(--border);background:rgba(255,255,255,.06);color:white;border-radius:13px;padding:10px 12px;font-weight:800;cursor:pointer}.btn:hover{transform:translateY(-1px)}.btn.green{background:rgba(0,255,136,.10);border-color:rgba(0,255,136,.30)}.btn.red{background:rgba(255,51,102,.10);border-color:rgba(255,51,102,.30)}.btn.blue{background:rgba(0,170,255,.10);border-color:rgba(0,170,255,.30)}.btn.amber{background:rgba(255,170,0,.10);border-color:rgba(255,170,0,.30)}input,select{width:100%;background:rgba(255,255,255,.055);border:1px solid var(--border);color:white;border-radius:14px;padding:11px 12px}option{background:#111827}label{font-size:12px;color:var(--muted);font-weight:800;margin-bottom:7px;display:block}.form{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;align-items:end}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px 8px;border-bottom:1px solid rgba(255,255,255,.06);font-size:13px;text-align:left}.table th{color:var(--muted);font-size:11px;text-transform:uppercase}.empty{padding:18px;border:1px dashed var(--border);border-radius:16px;color:var(--muted)}.code{white-space:pre-wrap;font:12px "JetBrains Mono";background:rgba(0,0,0,.25);border:1px solid var(--border);border-radius:16px;padding:14px;max-height:260px;overflow:auto}.alert{padding:13px;border:1px solid var(--border);border-radius:16px;background:rgba(255,255,255,.04);margin-bottom:10px}.toastwrap{position:fixed;right:18px;bottom:18px;z-index:99;display:grid;gap:10px}.toast{padding:12px 14px;border:1px solid var(--border);border-radius:14px;background:#101018;box-shadow:0 20px 50px rgba(0,0,0,.35);font-size:13px}canvas{width:100%!important;max-height:320px}@media(max-width:1300px){.shell{grid-template-columns:84px 1fr}.right{display:none}.brand h1,.brand small,.nav span,.sidefoot{display:none}.nav{justify-content:center}}@media(max-width:900px){.shell{display:block}.kpis,.two,.three,.form{grid-template-columns:1fr}aside{position:relative;height:auto}.nav span,.brand h1,.brand small{display:inline}.nav{justify-content:flex-start}}
</style>
</head>
<body>
<div class="shell"><aside><div class="brand"><div class="logo"><i data-lucide="activity"></i></div><div><h1>ATLAS</h1><small><span class="pulse green"></span> Trading OS</small></div></div><nav id="nav"></nav><div class="sidefoot"><div><span>Uptime</span><span id="uptime">00:00:00</span></div><div><span>Version</span><span>v1.0.0</span></div></div></aside><main><header><div class="head"><span id="market" class="pill"><span class="dot"></span> MARKET</span><span id="utc" class="pill mono"></span><span id="et" class="pill mono"></span></div><div class="head"><span id="pnl" class="pnl green">$0.00 ↑</span><span id="kill" class="pill green"><span class="dot"></span> DISARMED</span><span class="pill"><i data-lucide="bell"></i><span id="alertCount">0</span></span><span id="lastRefresh" class="pill mono">refresh --</span></div></header><section id="content"></section></main><section class="right"><h3>Live Alerts & Signals</h3><div id="alerts"></div></section></div><div class="toastwrap" id="toasts"></div>
<script>
const API=location.origin.includes("47.130.131.155")?"http://47.130.131.155:8080":"http://localhost:8080";const state={page:"overview",boot:Date.now(),health:null,risk:null,agents:[],strategies:[],portfolio:null,lastBacktest:null,alerts:[],charts:{}};const nav=[["overview","Overview","layout-grid"],["live","Live Trading","chart-line"],["strategies","Strategies","brain"],["backtesting","Backtesting","history"],["risk","Risk & Kill Switch","shield"],["agents","Agents","bot"],["scout","Scout Network","radar"],["brief","Intelligence Brief","newspaper"],["settings","Settings","settings"]];const $=id=>document.getElementById(id),money=n=>Number(n||0).toLocaleString(undefined,{style:"currency",currency:"USD",maximumFractionDigits:2}),cls=n=>Number(n||0)>=0?"green":"red";function api(p,o={}){return fetch(API+p,{headers:{"Content-Type":"application/json"},...o}).then(async r=>{let t=await r.text(),d={};try{d=t?JSON.parse(t):{}}catch{d={raw:t}}if(!r.ok)throw Error(d.detail||d.message||t||r.statusText);return d})}function toast(m,t="blue"){let e=document.createElement("div");e.className="toast";e.innerHTML=`<b class="${t}">${t.toUpperCase()}</b><br>${m}`;$("toasts").appendChild(e);setTimeout(()=>e.remove(),4200)}function empty(m){return`<div class="empty">${m}</div>`}function ago(ts){if(!ts)return"never";let s=Math.floor((Date.now()-new Date(ts))/1000);return s<60?`${s}s ago`:s<3600?`${Math.floor(s/60)}m ago`:`${Math.floor(s/3600)}h ago`}function init(){$("nav").innerHTML=nav.map(([id,l,i])=>`<button class="nav ${id=="overview"?"active":""}" onclick="page('${id}')" data-page="${id}"><i data-lucide="${i}"></i><span>${l}</span></button>`).join("");lucide.createIcons();renderAlerts();refresh(true);setInterval(()=>refresh(true),10000);setInterval(clock,1000)}function page(p){state.page=p;document.querySelectorAll(".nav").forEach(b=>b.classList.toggle("active",b.dataset.page==p));render()}function clock(){let n=new Date(),s=Math.floor((Date.now()-state.boot)/1000);$("utc").textContent="UTC "+n.toISOString().slice(11,19);$("et").textContent="ET "+n.toLocaleTimeString("en-US",{timeZone:"America/New_York",hour12:false});$("uptime").textContent=new Date(s*1000).toISOString().slice(11,19)}async function refresh(silent=false){await Promise.allSettled([api("/health").then(d=>state.health=d),api("/api/risk/status").then(d=>state.risk=d),api("/api/agents/registry").then(d=>state.agents=Array.isArray(d)?d:[]),api("/api/strategies").then(d=>state.strategies=Array.isArray(d)?d:(d.strategies||[])),api("/api/portfolio/summary").then(d=>state.portfolio=d).catch(()=>state.portfolio={portfolio_value:100000,daily_pnl:0,positions:[]})]);header();render();if(!silent)toast("Dashboard refreshed","green")}function header(){let k=state.health?.services?.kill_switch||"unknown",armed=String(k).toLowerCase().includes("armed")&&!String(k).toLowerCase().includes("disarmed");$("kill").className=`pill ${armed?"red":"green"}`;$("kill").innerHTML=`<span class="dot"></span> ${armed?"ARMED":"DISARMED"}`;$("lastRefresh").textContent="refresh "+new Date().toLocaleTimeString();let open=marketOpen();$("market").className=`pill ${open?"green":"red"}`;$("market").innerHTML=`<span class="dot"></span> ${open?"MARKET OPEN":"MARKET CLOSED"}`;let pnl=state.portfolio?.daily_pnl||0;$("pnl").className=`pnl ${cls(pnl)}`;$("pnl").textContent=`${money(pnl)} ${pnl>=0?"↑":"↓"}`}function marketOpen(){let e=new Date(new Date().toLocaleString("en-US",{timeZone:"America/New_York"})),d=e.getDay(),m=e.getHours()*60+e.getMinutes();return d>0&&d<6&&m>=570&&m<=960}function title(t,s){return`<div class="title"><div><h2>${t}</h2><p>${s}</p></div><button class="btn blue" onclick="refresh()">Refresh All</button></div>`}function card(t,b){return`<div class="card"><h3>${t}</h3>${b}</div>`}function render(){let c=$("content");if(state.page=="overview")c.innerHTML=overview();if(state.page=="live")c.innerHTML=live();if(state.page=="strategies")c.innerHTML=strategies();if(state.page=="backtesting")c.innerHTML=backtesting();if(state.page=="risk")c.innerHTML=risk();if(state.page=="agents")c.innerHTML=agents();if(state.page=="scout")c.innerHTML=scout();if(state.page=="brief")c.innerHTML=brief();if(state.page=="settings")c.innerHTML=settings();lucide.createIcons();charts()}function overview(){let h=state.health?.services||{},r=state.risk||{},a=state.strategies||[],active=a.filter(x=>(x.status||"").toLowerCase()=="active").length,score=h.timescaledb=="ok"&&h.feature_store?.status=="ok"&&h.last_data_timestamp?.status=="ok"?96:72;return title("Overview","Live ATLAS command center with 10-second auto-refresh")+`<div class="grid kpis">${card("Total Portfolio Value",`<div class="metric">${money(state.portfolio?.portfolio_value||100000)}</div><canvas id="spark"></canvas><p class="sub">Live portfolio endpoint</p>`)}${card("Daily PnL",`<div class="metric ${cls(state.portfolio?.daily_pnl)}">${money(state.portfolio?.daily_pnl||0)}</div><p class="sub">Current paper portfolio</p>`)}${card("Active Strategies",`<div class="metric blue">${active}/${a.length}</div><p class="sub">Database strategy status</p>`)}${card("System Health",`<div class="metric green">${score}%</div><div style="height:10px;background:rgba(255,255,255,.08);border-radius:99px"><div style="height:10px;width:${score}%;background:var(--green);border-radius:99px"></div></div>`)}</div><br><div class="grid two">${card("Portfolio Equity Curve",`<canvas id="equity"></canvas>`)}${card("Asset Distribution",`<canvas id="assets"></canvas>`)}</div><br><div class="grid three">${card("Polygon Feed",`<div class="metric ${h.last_data_timestamp?.status=="ok"?"green":"amber"}">${h.last_data_timestamp?.status||"unknown"}</div><p class="sub">Last: ${h.last_data_timestamp?.timestamp||"--"} | Age: ${h.last_data_timestamp?.age_seconds??"--"}s</p>${["AAPL","MSFT","NVDA","TSLA","AMZN"].map(s=>`<span class="chip green"><span class="dot"></span>${s}</span>`).join("")}`)}${card("Binance Feed",`<div class="metric green">LIVE</div>${["BTC/USDT","ETH/USDT","SOL/USDT"].map(s=>`<span class="chip green"><span class="dot"></span>${s}</span>`).join("")}`)}${card("Feature Store",`<div class="metric ${h.feature_store?.status=="ok"?"green":"red"}">${h.feature_store?.status||"unknown"}</div><p class="sub">${h.feature_store?.last_computed||"--"}</p>`)}</div><br><div class="grid three">${card("Active Agents",agentMini())}${card("Recent Signals",empty("Signal endpoint not available yet"))}${card("Kill Switch",`<div class="metric ${r.kill_switch_armed?"red":"green"}">${r.kill_switch_armed?"ARMED":"DISARMED"}</div><p class="sub">${r.reason||"No active reason"}</p>`)}</div>`}function agentMini(){return(state.agents||[]).slice(0,6).map(a=>`<span class="chip ${a.status=="running"?"green":a.status=="error"?"red":"blue"}"><span class="dot"></span>${a.name}: ${a.status} · ${ago(a.last_heartbeat)}</span>`).join("")||empty("No agents returned")}function live(){return title("Live Trading","Paper execution and positions monitor")+`<div class="grid two">${card("Live Price Chart / Paper Trade",`<div class="form"><div><label>Symbol</label><select id="tradeSymbol">${["AAPL","MSFT","NVDA","TSLA","AMZN","BTCUSDT","ETHUSDT","SOLUSDT"].map(s=>`<option>${s}</option>`)}</select></div><div><label>Side</label><select id="tradeSide"><option>buy</option><option>sell</option></select></div><div><label>Qty</label><input id="tradeQty" value="1"></div><button class="btn green" onclick="paperTrade()">Paper Trade</button></div><canvas id="priceChart"></canvas><p class="sub">PAPER TRADING</p>`)}${card("Recent Order Response",`<div id="orderResult">${empty("Submit a paper trade")}</div>`)}</div><br>${card("Positions",`<table class="table"><thead><tr><th>Symbol</th><th>Side</th><th>Qty</th><th>PnL</th><th>Status</th></tr></thead><tbody>${(state.portfolio?.positions||[]).map(p=>`<tr><td>${p.symbol}</td><td>${p.side||"--"}</td><td>${p.qty||"--"}</td><td class="${cls(p.unrealized_pnl)}">${money(p.unrealized_pnl)}</td><td>${p.status||"paper"}</td></tr>`).join("")||`<tr><td colspan="5">${empty("No positions returned")}</td></tr>`}</tbody></table>`)}`}async function paperTrade(){let symbol=$("tradeSymbol").value,broker=symbol.includes("USDT")?"binance_testnet":"alpaca";try{let d=await api("/api/execution/test-order",{method:"POST",body:JSON.stringify({broker,symbol,side:$("tradeSide").value,qty:Number($("tradeQty").value||1),order_type:"market",test_only:true})});$("orderResult").innerHTML=`<div class="code">${JSON.stringify(d,null,2)}</div>`;toast("Paper trade executed","green")}catch(e){$("orderResult").innerHTML=`<div class="code red">${e.message}</div>`;toast(e.message,"red")}}function strategies(){let a=state.strategies||[];return title("Strategies","AI strategy list and generation")+card("Generate Strategy",`<div class="form"><div><label>Asset</label><select id="genAsset"><option>us_equities</option><option>crypto</option></select></div><div><label>Symbol</label><input id="genSymbol" value="AAPL"></div><div><label>Style</label><select id="genStyle"><option>momentum</option><option>mean_reversion</option><option>breakout</option></select></div><button class="btn green" onclick="genStrat()">Generate</button></div><div id="genResult"></div>`)+`<br><div class="grid three">${a.slice(0,24).map(s=>card(s.name||s.id||"Strategy",`<span class="chip blue">${s.status||"unknown"}</span><p class="sub">${s.symbol||s.symbols||"multi-symbol"}</p><div class="metric ${Number(s.sharpe||s.sharpe_ratio||0)>1?"green":Number(s.sharpe||s.sharpe_ratio||0)<0?"red":"amber"}">${Number(s.sharpe||s.sharpe_ratio||0).toFixed(2)}</div><p class="sub">Sharpe</p><button class="btn blue" onclick="runBacktest('${s.id||""}','${s.symbol||"AAPL"}')">Backtest</button>`)).join("")||empty("No strategies returned")}</div>`}async function genStrat(){try{let d=await api("/api/strategies/generate",{method:"POST",body:JSON.stringify({asset_class:$("genAsset").value,symbol:$("genSymbol").value,style:$("genStyle").value})});$("genResult").innerHTML=`<br><div class="code">${JSON.stringify(d,null,2)}</div>`;refresh(true)}catch(e){$("genResult").innerHTML=`<p class="red">${e.message}</p>`}}function backtesting(){return title("Backtesting","2-year history, daily equity, 70/30 split, Monte Carlo")+card("Run Backtest",`<div class="form"><div><label>Symbol</label><select id="btSymbol">${["AAPL","MSFT","NVDA","TSLA","AMZN"].map(s=>`<option>${s}</option>`)}</select></div><div><label>Qty</label><input id="btQty" value="10"></div><div><label>Split</label><span class="chip green">70% Backtest / 30% Monte Carlo</span></div><button class="btn green" onclick="runBacktest('',document.getElementById('btSymbol').value)">Run</button></div>`)+`<br><div id="btResult">${state.lastBacktest?btResult(state.lastBacktest):empty("Run a backtest")}</div>`}async function runBacktest(id="",symbol="AAPL"){state.page="backtesting";render();$("btResult").innerHTML=card("Running","<p class='sub'>Backtest in progress...</p>");try{let d=await api("/api/backtest/run",{method:"POST",body:JSON.stringify({strategy_id:id,symbol,qty:Number($("btQty")?.value||10)})});state.lastBacktest=d;render();toast("Backtest completed","green")}catch(e){$("btResult").innerHTML=card("Error",`<p class="red">${e.message}</p>`)}}function btResult(d){let bt=d.results?.backtest||{},mc=d.results?.monte_carlo||{},m=mc.parameters?.monte_carlo||{};return`<div class="grid two">${card("Equity Curve",`<canvas id="btChart"></canvas><p class="sub">Daily equity points: ${(bt.equity_curve||[]).length} / ${(mc.equity_curve||[]).length}</p>`)}${card("Monte Carlo",`<div class="metric ${m.status=="pass"?"green":"amber"}">${m.status||"unknown"}</div><p class="sub">Runs: ${m.runs||"--"} | Points: ${m.daily_points||"--"}</p><div class="code">${JSON.stringify(m,null,2)}</div>`)}</div><br><div class="grid three">${card("Sharpe",`<div class="metric ${Number(bt.sharpe_ratio)>1?"green":Number(bt.sharpe_ratio)<0?"red":"amber"}">${Number(bt.sharpe_ratio||0).toFixed(2)}</div>`)}${card("Max Drawdown",`<div class="metric red">${(Number(bt.max_drawdown||0)*100).toFixed(2)}%</div>`)}${card("Trades",`<div class="metric blue">${bt.total_trades||0}</div>`)}</div>`}function risk(){let r=state.risk||{},armed=r.kill_switch_armed,cap=Number(r.capital||100000),d=Number(r.daily_loss_usd||0),w=Number(r.weekly_loss_usd||0);return title("Risk & Kill Switch","Confirmed execution blocking when armed")+`<div class="card" style="text-align:center;padding:34px"><div class="metric ${armed?"red":"green"}" style="font-size:54px">${armed?"ARMED":"DISARMED"}</div><p class="sub">${r.reason||"Trading allowed"}</p><button class="btn red" onclick="ks('arm')">ARM</button> <button class="btn green" onclick="ks('disarm')">DISARM</button></div><br><div class="grid two">${meter("Daily Loss",d,cap*.02)}${meter("Weekly Loss",w,cap*.04)}</div><br>${card("Simulate PnL",`<div class="form"><div><label>Loss</label><input id="loss" value="2500"></div><button class="btn amber" onclick="sim()">Fire Simulation</button></div><div id="simResult"></div>`)}`}function meter(t,v,l){let p=Math.min(100,Math.abs(v)/l*100);return card(t,`<div class="metric ${p>80?"red":"green"}">${money(v)} / ${money(l)}</div><div style="height:13px;background:rgba(255,255,255,.08);border-radius:99px"><div style="height:13px;width:${p}%;background:${p>80?"var(--red)":"var(--green)"};border-radius:99px"></div></div>`)}async function ks(action){let reason=action=="arm"?prompt("Reason?","dashboard manual trigger"):"dashboard disarm";if(action=="arm"&&!reason)return;try{await api("/api/risk/kill-switch",{method:"POST",body:JSON.stringify({action,reason})});toast(`Kill switch ${action}ed`,"green");refresh(true)}catch(e){toast(e.message,"red")}}async function sim(){try{let d=await api("/api/risk/simulate-pnl",{method:"POST",body:JSON.stringify({loss_usd:Number($("loss").value||0),weekly_loss_usd:Number($("loss").value||0)})});$("simResult").innerHTML=`<br><div class="code">${JSON.stringify(d,null,2)}</div>`;refresh(true)}catch(e){$("simResult").innerHTML=e.message}}function agents(){return title("Agents","Registry and lifecycle controls")+card("Agent Registry",`<table class="table"><thead><tr><th>Name</th><th>Type</th><th>Status</th><th>Heartbeat</th><th>Actions</th></tr></thead><tbody>${(state.agents||[]).map(a=>`<tr><td>${a.name}</td><td>${a.agent_type}</td><td><span class="chip ${a.status=="running"?"green":a.status=="error"?"red":"blue"}"><span class="dot"></span>${a.status}</span></td><td>${ago(a.last_heartbeat)}</td><td><button class="btn" onclick="agent('${a.name}','pause')">Pause</button> <button class="btn" onclick="agent('${a.name}','resume')">Resume</button> <button class="btn red" onclick="agent('${a.name}','kill')">Kill</button></td></tr>`).join("")}</tbody></table>`)}async function agent(n,a){try{await api(`/api/agents/${n}/${a}`,{method:"POST"});refresh(true)}catch(e){toast(e.message,"red")}}function scout(){return title("Scout Network","YouTube, Reddit and Discord scout interface")+`<div class="grid three">${card("YouTube Scout",`<div class="metric green">READY</div><p class="sub">Transcript-first with yt-dlp fallback after patch</p>`)}${card("Reddit Scout",`<div class="metric blue">READY</div>`)}${card("Discord Scout",`<div class="metric amber">DEFERRED</div>`)}</div><br>${card("Test Scout",`<div class="form"><div><label>Source</label><select id="scoutSource"><option>youtube</option><option>reddit</option><option>discord</option></select></div><div><label>Query</label><input id="scoutQuery" value="anchored vwap trading strategy"></div><div><label>Max</label><input id="scoutMax" value="2"></div><button class="btn green" onclick="runScout()">Run</button></div><div id="scoutResult"></div>`)}`}async function runScout(){try{let d=await api("/api/scouts/test",{method:"POST",body:JSON.stringify({source:$("scoutSource").value,query:$("scoutQuery").value,max_results:Number($("scoutMax").value||2),limit:Number($("scoutMax").value||2)})});$("scoutResult").innerHTML=`<br>${(d.hypotheses||[]).map(h=>card(h.source_url||h.source,`<p>${h.description||""}</p><p class="sub">Confidence: ${((h.confidence||0)*100).toFixed(1)}%</p>`)).join("")||empty("No new hypotheses; duplicates may be skipped")}`}catch(e){$("scoutResult").innerHTML=`<p class="red">${e.message}</p>`}}function brief(){return title("Intelligence Brief","Market/risk/strategy report")+card("Generate Brief",`<button class="btn green" onclick="genBrief()">Generate Brief</button><div id="briefResult">${empty("Generate live intelligence brief")}</div>`)}async function genBrief(){try{let d=await api("/api/dashboard/generate-brief",{method:"POST",body:JSON.stringify({})});$("briefResult").innerHTML=`<br><div class="code">${JSON.stringify(d,null,2)}</div>`}catch(e){$("briefResult").innerHTML=`<br><div class="code">${JSON.stringify({status:"dashboard summary fallback",message:e.message,health:state.health?.status,risk:state.risk,strategies:state.strategies.length},null,2)}</div>`}}function settings(){return title("Settings","Live API configuration")+card("Configuration",`<p>API Base: <span class="mono blue">${API}</span></p><p class="sub">Auto-refresh: 10 seconds</p><p class="sub">Shortcuts: K Risk, G Strategies, R Refresh</p>`)}function renderAlerts(){$("alerts").innerHTML=(state.alerts.length?state.alerts:[{t:"now",title:"System ready",msg:"Waiting for live alerts",type:"green"}]).map(a=>`<div class="alert"><b class="${a.type}">${a.title}</b><p class="sub">${a.msg}</p><small>${a.t}</small></div>`).join("")}function charts(){Object.values(state.charts).forEach(c=>c?.destroy?.());state.charts={};let mk=(id,type,data,opt={})=>{let e=$(id);if(!e)return;state.charts[id]=new Chart(e,{type,data,options:{responsive:true,plugins:{legend:{labels:{color:"#c8cfdb"}}},scales:{x:{ticks:{color:"#8c92a3"},grid:{color:"rgba(255,255,255,.04)"}},y:{ticks:{color:"#8c92a3"},grid:{color:"rgba(255,255,255,.04)"}}},...opt}})};mk("spark","line",{labels:["1","2","3","4","5"],datasets:[{data:[100,101,100.6,102,102.4],borderColor:"#00ff88",backgroundColor:"rgba(0,255,136,.12)",fill:true,tension:.4,pointRadius:0}]},{scales:{x:{display:false},y:{display:false}}});mk("equity","line",{labels:["May","Jun","Jul","Aug","Sep","Oct","Nov","Dec","Jan","Feb","Mar","Apr","May"],datasets:[{label:"Portfolio",data:[100,101,103,99,104,108,106,111,115,112,119,123,126],borderColor:"#00ff88",backgroundColor:"rgba(0,255,136,.12)",fill:true,tension:.35}]});mk("assets","doughnut",{labels:["AAPL","MSFT","NVDA","TSLA","AMZN","BTC","ETH","SOL"],datasets:[{data:[16,14,18,10,12,15,9,6],backgroundColor:["#00ff88","#00aaff","#ffaa00","#ff3366","#8b5cf6","#22c55e","#06b6d4","#f97316"]}]},{scales:{}});mk("priceChart","line",{labels:["09:30","10:00","11:00","12:00","13:00","14:00","15:00","16:00"],datasets:[{label:"Price",data:[100,101.4,100.8,102.2,101.9,103.1,102.8,104],borderColor:"#00aaff",backgroundColor:"rgba(0,170,255,.08)",fill:true,tension:.25}]});if(state.lastBacktest){let bt=state.lastBacktest.results?.backtest?.equity_curve||[],mc=state.lastBacktest.results?.monte_carlo?.equity_curve||[];mk("btChart","line",{labels:[...bt,...mc].map(x=>x.t).slice(-220),datasets:[{label:"Backtest 70%",data:bt.map(x=>x.v).slice(-220),borderColor:"#00ff88"},{label:"Monte Carlo 30%",data:mc.map(x=>x.v).slice(-220),borderColor:"#ffaa00"}]})}}document.addEventListener("keydown",e=>{let k=e.key.toLowerCase();if(k=="r")refresh();if(k=="k")page("risk");if(k=="g")page("strategies")});init();
</script>
</body>
</html>
